let toastTimer;
function toast(message,error=false){clearTimeout(toastTimer);$('#toastText').textContent=String(message);$('#toast').classList.toggle('error',error);$('#toast').classList.add('show');$('#bottomStatus').textContent=String(message);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function status(message){$('#sceneStatus').textContent=message;if(message!=='实时 3D 预览')$('#bottomStatus').textContent=message;}
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let scene;
scene=createScene($('#viewport'),toast,()=>refreshLayers());
if(import.meta.env.DEV)window.__workbench={scene,state};
async function callScene(method,...args){if(typeof scene[method]!=='function')throw new Error('该操作尚未就绪，请稍后重试。');return scene[method](...args);}
async function runTask(label,fn){if(state.busy)return;state.busy=true;status(label);$$('.generate-btn').forEach(b=>b.disabled=true);try{const result=await fn();refreshLayers();return result}catch(error){if(error.name==='AbortError')toast('已取消生成，视角已恢复可操作。');else toast(error.message||'操作失败，请重试。',true)}finally{state.busy=false;updateButtons();syncLock();status('实时 3D 预览');}}
function updateButtons(){const uvMap=!!state.source&&!state.source.projectionSnapshot&&state.uvMatch>.7;$('#replaceUVBtn').classList.toggle('generate-btn',uvMap);$('#replaceUVBtn').classList.toggle('secondary-button',!uvMap);const box=$('.fine-tune');if(uvMap&&$('#replaceUVBtn').parentElement!==box.parentElement)box.before($('#replaceUVBtn'));else if(!uvMap&&$('#replaceUVBtn').parentElement!==box)box.append($('#replaceUVBtn'));$('#projectBtn').classList.toggle('secondary-generate',uvMap);$('#opacitySlider').disabled=!(scene?.getLayers?.()||[]).length;for(const id of ['projectBtn','replaceUVBtn','downloadSource'])$(`#${id}`).disabled=!state.source||state.busy;$('#projectBtn').title=state.source?'':'先生成或上传一张图片';$$('.generate-btn:not(#projectBtn)').forEach(b=>b.disabled=state.busy);$('#discardBtn').hidden=!state.source;$('#projectEmpty').hidden=!!state.source;$('#projectBtn').hidden=!state.source;$('#discardBtn').hidden=!state.source;$('#bannerProject').disabled=$('#unlockView').disabled=state.busy;}
function openAPI(){if(state.serverConfig){$('#envChoice').hidden=false;$('#useEnvConfig').checked=state.useServerConfig;}toggleEnvFields();$('#apiBase').value=state.api.baseUrl;$('#apiModel').value=state.api.model;$('#apiKey').value=state.api.apiKey;toggleEnvFields();$('#apiModal').classList.add('open');}
function readDataURL(file){return new Promise((resolve,reject)=>{if(!file?.type.startsWith('image/'))return reject(Error('请选择 PNG、JPG 或 WebP 图片。'));if(file.size>40*1024*1024)return reject(Error('图片超过 40 MB，请先压缩。'));const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('图片读取失败。'));reader.readAsDataURL(file);});}
async function loadSource(url,name='生成图片',projectionSnapshot=null,generation=null){state.uvMatch=projectionSnapshot?0:await (scene.uvMatchScore?.(url)||0);const image=new Image();image.src=url;await image.decode();state.source={url,name,projectionSnapshot,generation,width:image.naturalWidth,height:image.naturalHeight};state.sources[state.channel]=state.source;await callScene('setTexture',url,{channel:state.channel,name});$('#sourcePreview').innerHTML='<img alt="待投射贴图">';$('#sourcePreview img').src=url;$('#overlayImage').src=url;$('#sourceMeta').textContent=`${name}${projectionSnapshot?' · 已锁定生成视角':''}`;$('#downloadSource').disabled=false;if(projectionSnapshot)callScene('lockView',projectionSnapshot);syncLock();$('#projectionOverlay').classList.add('visible');$('#overlayToggle').classList.add('active');updateOverlay();updateSizeFacts();updateButtons();updateButtons();if(!generation)toast(state.uvMatch>.7?`这张图和模型 UV 吻合（${Math.round(state.uvMatch*100)}%），已把「直接替换」设为主按钮。`:'图片已加载，转到对应角度后投射。');}
// Three independent numbers: what we asked for, what the provider really returned, what the UV bake will be.
function updateSizeFacts(){const src=state.source;$('#sizeFacts').hidden=!src;if(!src)return;const g=src.generation;$('#factRequested').textContent=g?.requestedSize||'—（上传图片）';const native=g?.requestedSize&&/^\d+x\d+$/.test(g.requestedSize)&&g.requestedSize!==`${src.width}x${src.height}`;$('#factActual').textContent=`${src.width} × ${src.height}${native?' · 与请求不符':''}`;$('#factActual').classList.toggle('warn',!!native);const bake=state.size;$('#factBake').textContent=`${bake} × ${bake}${src.width<bake?` · 由 ${src.width}px 图片投射，非原生细节`:''}`;$('#factActual').textContent+=g?.matte?` · 已抠底 ${(g.matte.removed*100).toFixed(0)}%`:'';$('#factTime').textContent=g?.timing?`${(g.timing.totalMs/1000).toFixed(1)} 秒${g.timing.upstreamMs?`（服务商 ${(g.timing.upstreamMs/1000).toFixed(1)} 秒）`:''}${g.timing.retries?` · 重试 ${g.timing.retries} 次`:''}`:'—';}
