function updateOverlay(){$('#overlayImage').style.opacity=Number($('#overlayOpacitySlider').value)/100;const scale=Number($('#scaleSlider').value)/100,x=Number($('#offsetXSlider').value),y=Number($('#offsetYSlider').value),angle=Number($('#rotationSlider').value);$('#projectionOverlay').style.transform=`translate(${x}%,${-y}%)`;$('#overlayImage').style.transform=`scale(${scale}) rotate(${-angle}deg)`;}
function refreshLayers(){if(typeof scene?.getLayers!=='function')return;const layers=scene.getLayers()||[];if(!layers.some(l=>l.id===state.selected))state.selected=layers.at(-1)?.id??null;$('#layerCount').textContent=layers.length;$('#layerList').innerHTML=layers.length?layers.slice().reverse().map(l=>`<div class="layer-item ${l.id===state.selected?'selected':''}" data-layer="${escapeHTML(l.id)}"><button class="layer-eye" data-eye="${escapeHTML(l.id)}" title="切换图层显隐">${I(l.visible===false?'eyeOff':'eye',15)}</button><div class="layer-thumb">${I(l.channel==='normal'?'layers':'image',16)}</div><div class="layer-copy"><strong>${escapeHTML(l.name||'贴图图层')}</strong><span>${l.channel==='normal'?'法线':'基础颜色'} · ${Math.round((l.opacity??1)*100)}%</span></div></div>`).join(''):'<div class="empty-layers">投射或替换贴图后，图层会出现在这里。</div>';$$('[data-layer]').forEach(el=>{const layer=layers.find(l=>String(l.id)===el.dataset.layer);el.onclick=e=>{if(e.target.closest('[data-eye]'))return;state.selected=layer.id;refreshLayers()};el.querySelector('[data-eye]').onclick=async()=>{await callScene('setLayer',layer.id,{visible:layer.visible===false});refreshLayers()};});const selected=layers.find(l=>l.id===state.selected);$('#opacitySlider').disabled=!selected;$('#opacitySlider').value=Math.round((selected?.opacity??1)*100);$('#opacityValue').textContent=$('#opacitySlider').value+'%';$('#deleteLayer').disabled=!selected;}
function activateWithin(selector,button){$$(selector).forEach(b=>b.classList.toggle('active',b===button));}
$$('[data-channel]').forEach(button=>button.onclick=async()=>{if(state.busy)return;state.channel=button.dataset.channel;activateWithin('[data-channel]',button);callScene('unlockView');syncLock();$('#generateLabel').textContent=state.channel==='normal'?'生成当前视角法线':'生成当前视角贴图';$('#channelLabel').textContent=state.channel==='normal'?'法线贴图':'基础颜色';$('#normalSection').hidden=state.channel!=='normal';$('#normalSpaceRow').hidden=state.channel!=='normal';$('#projectionHint').textContent=state.channel==='normal'?'局部法线 PNG 可按当前视角投射，并转换方向后烘焙到 UV。已有 UV 法线可直接替换。':'只烘焙当前视角可见表面。转动模型后可继续投射。';const savedSource=state.sources[state.channel];state.source=savedSource;if(savedSource){await loadSource(savedSource.url,savedSource.name,savedSource.projectionSnapshot);}else{$('#sourcePreview').innerHTML='<button id="sourceEmptyAgain">上传 PNG / JPG</button>';$('#sourceEmptyAgain').onclick=()=>$('#textureInput').click();$('#sourceMeta').textContent='此通道尚未加载图片';$('#projectionOverlay').classList.remove('visible');$('#overlayToggle').classList.remove('active');}updateButtons();});
