    const w=state.source.width;toast(`${body.model} 用时 ${(generation.timing.totalMs/1000).toFixed(1)} 秒，实际 ${w}×${state.source.height}${generation.requestedSize!==`${w}x${state.source.height}`&&/x/.test(generation.requestedSize)?`（请求 ${generation.requestedSize}）`:''}。视角已锁定，确认对齐后点击投射。`,generation.requestedSize!==`${w}x${state.source.height}`&&/x/.test(generation.requestedSize));
