// Generated images keep the grey snapshot background; cut it to alpha so projection skips it.
async function autoMatte(image,snapshot,channel){if(channel==='normal')return {image,matte:null};
  const t=performance.now();let url=image,matte=null;
  if($('#matteToggle').checked&&snapshot?.mask){const r=await matteImage(image,{maskUrl:snapshot.mask,tolerance:Number($('#matteTolerance').value)});url=r.url;matte={removed:r.removed,ms:0,background:r.background};}
  if($('#delightToggle').checked)url=(await delightImage(url,{strength:Number($('#delightStrength').value)/100})).url;
  if(matte)matte.ms=Math.round(performance.now()-t);
  return {image:url,original:image,matte};}
// AI normal images: keep relief only and project as tangent detail; raw mode keeps the old camera-space path.
async function prepareNormal(image,snapshot){if(!$('#normalDetailOnly').checked)return {image,space:'view',detail:false};
  const r=await detailNormal(image,{maskUrl:snapshot?.mask});return {image:r.url,original:image,space:'tangent',detail:true};}
$('#matteTolerance').oninput=e=>$('#matteToleranceValue').textContent=e.target.value;
// ── Six-view automatic texturing ─────────────────────────────────────────────
const FACE_NAMES={front:'前',back:'后',left:'左',right:'右',top:'上',bottom:'下',inner_left:'右腿内侧',inner_right:'左腿内侧'};
$('#facePicks').innerHTML=Object.entries(FACE_NAMES).filter(([k])=>!k.startsWith('inner_')).map(([k,n])=>`<label><input type="checkbox" value="${k}" checked>${n}</label>`).join('');
const currentModel=()=>$('#modelSelect').value==='__custom'?$('#customModel').value.trim():$('#modelSelect').value;
function checkCanGenerate(){if(!state.modelLoaded)throw Error('请先导入模型。');if(!state.useServerConfig&&!state.api.apiKey){openAPI();throw Error('请先填写你自己的 API 密钥。');}if(state.channel==='color'&&!state.reference)throw Error('请先上传一张参考图片。');if(!currentModel())throw Error('请先选择或输入图片模型。');}
function renderFaceGrid(){const m=state.multi;$('#faceGrid').innerHTML=m?Object.entries(m.views).map(([f,v])=>{const label=v.status==='done'?`${v.width}px · ${(v.ms/1000).toFixed(0)} 秒`:v.status==='running'?`生成中 ${((performance.now()-v.started)/1000).toFixed(0)} 秒`:v.status==='error'?'失败':v.status==='cancelled'?'已取消':'等待';return `<div class="face-cell ${v.status}${v.include?'':' excluded'}" title="${escapeHTML(v.error||'')}"><img alt="${FACE_NAMES[f]}面" src="${v.image||v.snapshot.image}"><div class="face-meta"><strong>${FACE_NAMES[f]}</strong><span>${escapeHTML(label)}</span></div><div class="face-actions"><label title="合并时使用这一面"><input type="checkbox" data-include="${f}" ${v.include?'checked':''} ${v.status==='done'?'':'disabled'}>用</label><button data-regen="${f}" title="重新生成这一面">↻</button><button data-look="${f}" title="转到这一面检查">看</button></div></div>`}).join(''):'';
  $('#sixMerge').hidden=!m||!Object.values(m.views).some(v=>v.status==='done');
  $$('[data-include]').forEach(el=>el.onchange=()=>{state.multi.views[el.dataset.include].include=el.checked;renderFaceGrid();});
  $$('[data-regen]').forEach(el=>el.onclick=()=>regenerateFace(el.dataset.regen));
  $$('[data-look]').forEach(el=>el.onclick=()=>{try{scene.viewFrom(el.dataset.look)}catch(e){toast(e.message,true)}});}
async function generateFace(face,signal){const m=state.multi,v=m.views[face];Object.assign(v,{status:'running',started:performance.now(),error:''});renderFaceGrid();
  const body={...state.api,model:m.model,useServerConfig:state.useServerConfig,prompt:buildGenerationPrompt({channel:m.channel,extra:$('#promptInput').value.trim(),view:face.replace('inner_',''),cut:face.startsWith('inner_')}),size:$('#apiSize').value.trim()||'auto',mode:'edits',image:v.snapshot.image,...(state.reference?{reference:state.reference}:{})};
  try{const r=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal});const j=await r.json();if(!r.ok)throw Error(j.error?.message||j.error||`接口请求失败（${r.status}）`);if(!j.image)throw Error('接口没有返回可用图片。');
    const img=new Image();img.src=j.image;await img.decode();const matted=m.channel==='normal'?await prepareNormal(j.image,v.snapshot):await autoMatte(j.image,v.snapshot,m.channel);v.space=matted.space||'view';Object.assign(v,{status:'done',image:matted.image,original:matted.original,matte:matted.matte,width:img.naturalWidth,height:img.naturalHeight,ms:performance.now()-v.started,include:true});
  }catch(e){Object.assign(v,{status:e.name==='AbortError'?'cancelled':'error',error:e.message});}
  renderFaceGrid();}
async function mergeFaces(){const m=state.multi,views=Object.values(m.views).filter(v=>v.status==='done'&&v.include);if(!views.length)throw Error('没有勾选可用的视角。');
  const t=performance.now();m.layerId=await callScene('projectViews',{views:views.map(v=>({image:v.image,snapshot:v.snapshot,normalSpace:v.space})),size:state.size,channel:m.channel,normalSpace:'view',normalBlend:m.channel==='normal'&&$('#normalBlend').checked,replaceId:m.layerId,fillOnly:!!m.fillOnly,name:m.label?`${m.label}${m.channel==='normal'?'·法线':''}`:m.channel==='normal'?'六面法线':'六面颜色'});
  return {count:views.length,bakeMs:performance.now()-t};}
function startSixTimer(controller){state.abort=controller;$('#sixCancel').hidden=false;const t0=performance.now();const tick=()=>{const m=state.multi,vs=Object.values(m.views),done=vs.filter(v=>v.status==='done').length,running=vs.filter(v=>v.status==='running').length;const doneMs=vs.filter(v=>v.status==='done').map(v=>v.ms),avg=doneMs.length?doneMs.reduce((x,y)=>x+y,0)/doneMs.length:50000,left=Math.max(0,Math.ceil((vs.length-done)/3)*avg-(performance.now()-t0)%avg);$('#sixLabel').textContent=running?`生成中 ${done}/${vs.length} · 已用 ${((performance.now()-t0)/1000).toFixed(0)} 秒 · 约剩 ${Math.max(5,Math.round(left/1000))} 秒`:'正在合并投射…';status($('#sixLabel').textContent);renderFaceGrid();};tick();state.timer=setInterval(tick,500);return t0;}
function stopSixTimer(){clearInterval(state.timer);state.abort=null;$('#sixCancel').hidden=true;$('#sixLabel').textContent='一键生成 6 面并投射';}
$('#sixBtn').onclick=()=>{if(state.busy)return;try{checkCanGenerate();}catch(e){return toast(e.message,true);}const faces=$$('#facePicks input:checked').map(el=>el.value);if(!faces.length)return toast('请至少勾选一个视角。',true);
  runTask('正在截取六面视角…',async()=>{callScene('unlockView');syncLock();const snaps=await callScene('captureFaces',faces);
    state.multi={channel:state.channel,model:currentModel(),layerId:null,fillOnly:false,label:'',views:Object.fromEntries(snaps.map(sn=>[sn.face,{snapshot:sn,status:'waiting',include:true}]))};
    const controller=new AbortController(),t0=startSixTimer(controller);
    // Three at a time: six simultaneous requests were measured to stall together at the provider.
    try{const queue=[...faces];await Promise.all(Array.from({length:Math.min(3,queue.length)},async()=>{while(queue.length&&!controller.signal.aborted)await generateFace(queue.shift(),controller.signal);}));
      for(const f of queue)Object.assign(state.multi.views[f],{status:'cancelled'});
      const vs=Object.values(state.multi.views),failed=vs.filter(v=>v.status!=='done');
      if(controller.signal.aborted&&!vs.some(v=>v.status==='done'))throw Object.assign(Error('已取消'),{name:'AbortError'});
      if(failed.length===vs.length)throw Error(`所有视角都没有生成成功：${failed[0].error}`);
      const sizes=[...new Set(vs.filter(v=>v.status==='done').map(v=>`${v.width}×${v.height}`))].join('、');
      const r=await mergeFaces();
      toast(`六面完成：${r.count} 面已合并烘焙到 ${state.size}×${state.size}（实际生成 ${sizes}），总用时 ${((performance.now()-t0)/1000).toFixed(0)} 秒。${failed.length?`有 ${failed.length} 面失败，可点 ↻ 单独重试。`:'转动检查，不满意的面点 ↻ 重新生成。'}`,!!failed.length);
    }finally{stopSixTimer();renderFaceGrid();}});};
function regenerateFace(face){if(state.busy||!state.multi)return;try{checkCanGenerate();}catch(e){return toast(e.message,true);}
  runTask(`正在重新生成「${FACE_NAMES[face]}」面…`,async()=>{const controller=new AbortController();startSixTimer(controller);
    try{await generateFace(face,controller.signal);const v=state.multi.views[face];if(v.status!=='done')throw Error(v.status==='cancelled'?'已取消。':`「${FACE_NAMES[face]}」面生成失败：${v.error}`);const r=await mergeFaces();toast(`「${FACE_NAMES[face]}」面已更新，${r.count} 面重新合并。`);}finally{stopSixTimer();renderFaceGrid();}});}
$('#sixCancel').onclick=()=>state.abort?.abort();
$('#sixMerge').onclick=()=>runTask('正在合并投射…',async()=>{const r=await mergeFaces();toast(`已按勾选的 ${r.count} 面重新合并，用时 ${(r.bakeMs/1000).toFixed(1)} 秒。`);});
// ── Section cut & parts ──────────────────────────────────────────────────────
const CUT_KEEP_NAMES={x:['右侧','左侧'],z:['前侧','后侧'],y:['上侧','下侧']};
function syncCut(){const c=scene.getCut?.();$$('#cutAxis [data-cut]').forEach(b=>b.classList.toggle('active',(b.dataset.cut||'')===(c?.axis||'')));$('#cutKeepRow').hidden=$('#cutOffsetRow').hidden=!c;if(c){const [pos,neg]=CUT_KEEP_NAMES[c.axis];const btns=$$('#cutKeep [data-keep]');btns[0].textContent=`保留${pos}`;btns[1].textContent=`保留${neg}`;btns.forEach(b=>b.classList.toggle('active',Number(b.dataset.keep)===c.keep));$('#cutOffset').value=Math.round(c.offset*100);$('#cutOffsetValue').textContent=`${Math.round(c.offset*100)}%`;}}
function changeCut(patch){try{const c=scene.getCut?.();if(patch===null)scene.setCut(null);else scene.setCut({axis:'x',keep:1,offset:0,...c,...patch});syncCut();}catch(e){toast(e.message,true);}}
$$('#cutAxis [data-cut]').forEach(b=>b.onclick=()=>changeCut(b.dataset.cut?{axis:b.dataset.cut}:null));
$$('#cutKeep [data-keep]').forEach(b=>b.onclick=()=>changeCut({keep:Number(b.dataset.keep)}));
$('#cutOffset').oninput=e=>changeCut({offset:Number(e.target.value)/100});
function updateCutUI(){const d=scene?.getModelShape?.();$('#innerFillBtn').hidden=!(d&&d.humanoid);}
function renderParts(){updateCutUI();const parts=scene.getParts?.()||[];$('#partsBox').hidden=parts.length<2;$('#partCount').textContent=parts.length;$('#partsList').innerHTML=parts.map(p=>`<div class="part-row${p.visible?'':' off'}"><button data-part-eye="${p.id}" title="${p.visible?'隐藏':'显示'}" aria-label="${p.visible?'隐藏':'显示'} ${escapeHTML(p.name)}">${I(p.visible?'eye':'eyeOff',14)}</button><span title="${escapeHTML(p.name)}">${escapeHTML(p.name)}${p.uv?'':' · 无UV'}</span><button class="quiet-text" data-part-solo="${p.id}">只看</button></div>`).join('');
  $$('[data-part-eye]').forEach(b=>b.onclick=()=>{try{const p=parts.find(x=>x.id===b.dataset.partEye);scene.setPartVisible(p.id,!p.visible);renderParts();}catch(e){toast(e.message,true);}});
  $$('[data-part-solo]').forEach(b=>b.onclick=()=>{try{scene.soloPart(b.dataset.partSolo);renderParts();}catch(e){toast(e.message,true);}});}
$('#showAllParts').onclick=()=>{try{scene.showAllParts();renderParts();}catch(e){toast(e.message,true);}};
$('#viewport').addEventListener('workbench-change',()=>{renderParts();syncCut();});
// Inner-leg fill: cut each half away in turn, generate the exposed side, and only fill texels earlier layers left empty.
$('#innerFillBtn').onclick=()=>{if(state.busy)return;try{checkCanGenerate();}catch(e){return toast(e.message,true);}
  runTask('正在切半截取内侧…',async()=>{callScene('unlockView');syncLock();const before=scene.getCut();const snaps=[];
    try{for(const [keep,face] of [[1,'left'],[-1,'right']]){scene.setCut({axis:'x',keep,offset:0});const [sn]=await callScene('captureFaces',[face]);snaps.push({...sn,face:`inner_${face}`});}}
    finally{scene.setCut(before);syncCut();}
    state.multi={channel:state.channel,model:currentModel(),layerId:null,fillOnly:true,label:'内侧补色',views:Object.fromEntries(snaps.map(sn=>[sn.face,{snapshot:sn,status:'waiting',include:true}]))};
    const controller=new AbortController(),t0=startSixTimer(controller);
    try{await Promise.all(snaps.map(sn=>generateFace(sn.face,controller.signal)));const vs=Object.values(state.multi.views);if(!vs.some(v=>v.status==='done'))throw Error(vs[0].status==='cancelled'?'已取消。':`内侧生成失败：${vs[0].error}`);
      const r=await mergeFaces();toast(`腿内侧已补色：${r.count} 个切半视角，只填充之前没贴到的地方，用时 ${((performance.now()-t0)/1000).toFixed(0)} 秒。`);}
    finally{stopSixTimer();renderFaceGrid();}});};
// ── PBR: hi-res transfer, soft edges, AO, material zones ───────────────────
$('#hiresBtn').onclick=()=>state.modelLoaded?$('#hiresInput').click():toast('请先导入模型。',true);
$('#hiresInput').onchange=e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;runTask('正在转烘焙原件高清贴图…',()=>callScene('transferHires',f,{size:Math.max(4096,state.size)}));};
$('#smoothBtn').onclick=()=>runTask('正在软化边…',async()=>{needModel();return callScene('smoothNormals');});
$('#aoBtn').onclick=()=>runTask('正在烘焙 AO…',()=>{needModel();return callScene('bakeAOMap',{size:Math.max(4096,state.size)});});
const needModel=()=>{if(!state.modelLoaded)throw Error('请先导入模型。');};
$('#zoneBtn').onclick=()=>runTask('正在按颜色分材质…',async()=>{needModel();await callScene('computeZones',{count:6});renderZones();});
$('#wear').oninput=e=>{$('#wearValue').textContent=e.target.value+'%';scene.setORMOptions({wear:Number(e.target.value)/100});};
$('#zoneStrength').oninput=e=>{$('#zoneStrengthValue').textContent=e.target.value+'%';scene.setORMOptions({zoneStrength:Number(e.target.value)/100});};
$('#aoStrength').oninput=e=>{$('#aoStrengthValue').textContent=e.target.value+'%';scene.setORMOptions({aoStrength:Number(e.target.value)/100});};
const ZONE_PRESETS={'钢 / 银':[1,.32],'抛光金':[1,.22],'旧铜':[.85,.5],'黑铁':[.8,.6],'木':[0,.75],'皮革':[0,.6],'布料':[0,.9],'宝石 / 漆':[0,.2]};
function renderZones(){const z=scene.getZones?.();$('#zoneDetails').hidden=!z;$('#zoneCount').textContent=z?`${z.length} 种`:'';const seen={};
  $('#zoneList').innerHTML=z?z.map(v=>{seen[v.label]=(seen[v.label]||0)+1;const name=z.filter(x=>x.label===v.label).length>1?`${v.label} ${seen[v.label]}`:v.label;
    return `<div class="zone-row"><span class="zone-swatch" style="background:${v.color}" title="占模型 ${Math.round(v.share*100)}%"><small>${Math.round(v.share*100)}%</small></span><div class="zone-head"><input class="zone-name" data-zone-name="${v.index}" value="${escapeHTML(name)}" aria-label="材质名称"><select class="zone-preset" data-zone-preset="${v.index}" aria-label="材质预设"><option value="">预设…</option>${Object.keys(ZONE_PRESETS).map(k=>`<option>${k}</option>`).join('')}</select></div><label>金属<input type="range" min="0" max="100" value="${Math.round(v.metal*100)}" data-zone-metal="${v.index}"><output>${v.metal.toFixed(2)}</output></label><label>粗糙<input type="range" min="0" max="100" value="${Math.round(v.rough*100)}" data-zone-rough="${v.index}"><output>${v.rough.toFixed(2)}</output></label></div>`;}).join(''):'';
  const bind=(sel,key)=>$$(sel).forEach(el=>{el.oninput=()=>{el.nextElementSibling.textContent=(el.value/100).toFixed(2);scene.setZone(Number(el.dataset[key]),{[key==='zoneMetal'?'metal':'rough']:el.value/100});};});
  bind('[data-zone-metal]','zoneMetal');bind('[data-zone-rough]','zoneRough');
  $$('[data-zone-preset]').forEach(el=>el.onchange=()=>{const v=ZONE_PRESETS[el.value];if(!v)return;scene.setZone(Number(el.dataset.zonePreset),{metal:v[0],rough:v[1],label:el.value});renderZones();});
  $$('[data-zone-name]').forEach(el=>el.onchange=()=>scene.setZone(Number(el.dataset.zoneName),{label:el.value}));
  $$('.zone-row').forEach((row,k)=>{const on=()=>{scene.highlightZone(k);row.classList.add('active');},off=()=>{scene.highlightZone(null);row.classList.remove('active');};row.onmouseenter=on;row.onmouseleave=off;row.onfocusin=on;row.onfocusout=off;});}
$('#exportUnity').onclick=()=>$('#exportModal').classList.remove('open')||runTask('正在导出 Unity 贴图…',async()=>{const size=Math.max(4096,state.size);await callScene('exportTexture',{channel:'unityMS',size});await callScene('exportTexture',{channel:'unityAO',size});toast('已导出 MetallicSmoothness 和 AO：拖进 URP Lit 的 Metallic Map 与 Occlusion Map，Source 选 Metallic Alpha。');});
$('#exportORM').onclick=()=>$('#exportModal').classList.remove('open')||runTask('正在导出 ORM…',()=>callScene('exportTexture',{channel:'orm',size:Math.max(4096,state.size)}));
refreshLayers();updateButtons();renderParts();syncCut();new ResizeObserver(updateFrame).observe($('#viewport'));updateFrame();

function toggleEnvFields(){const use=!!state.serverConfig&&$('#useEnvConfig').checked;$('#apiBase').disabled=use;$('#apiKey').disabled=use;if(use){$('#apiBase').value=state.serverConfig.baseUrl;$('#apiKey').value='';$('#apiKey').placeholder='由本地服务读取，不发送给页面';}}
$('#useEnvConfig').onchange=toggleEnvFields;
$('#modelSelect').onchange=e=>{showModelFacts(e.target.value);$('#customModel').hidden=e.target.value!=='__custom';if(e.target.value!=='__custom')state.api.model=e.target.value;localStorage.setItem('texture-workbench-model',state.api.model);};
// Measured on Lumina 2026-11-02 with the spaceship benchmark (same view, reference and prompt). Not a provider guarantee.
const FRIENDLY={'doubao-seedream-5-0-260128':'Seedream 5 · 真 4K · 推荐','doubao-seedream-5-0-lite-260128':'Seedream 5 Lite · 真 4K','doubao-seedream-4-5-251128':'Seedream 4.5 · 4K','gemini-3-pro-image-preview':'Gemini 3 Pro · 1K · 较快','gemini-3.1-flash-image-preview':'Gemini 3.1 Flash · 1K','gpt-image-2.5-sunburst':'GPT Image 2.5 · 最高 2K','flux-kontext-pro':'Flux Kontext Pro · 1K'};
const modelLabel=m=>FRIENDLY[m]||m;
const MEASURED={'doubao-seedream-5-0-260128':'真 4K、轮廓贴合最好，约 1 分钟一张。','doubao-seedream-5-0-lite-260128':'实测：返回真实 4096×4096，轮廓贴合好，约 45 秒。','gemini-3-pro-image-preview':'实测：无论请求多大都返回 1024×1024，约 30 秒，轮廓基本贴合。','gemini-3.1-flash-image-preview':'实测：返回 1024×1024，会重画轮廓，不适合投射。','gpt-image-2.5-sunburst':'实测：请求 4096 只返回 1024；请求 2048x2048 可得真实 2048。轮廓会偏移。','gpt-image-2.5-flare':'未实测。','flux-kontext-pro':'实测：返回 1024×1024，约 77 秒，偏柔。','doubao-seedream-4-5-251128':'实测：返回 4096，但这次轮廓重画，不适合投射。'};
function showModelFacts(model){$('#modelFacts').textContent=MEASURED[model]||'该模型未实测。请求尺寸只是参数，实际尺寸以返回图片为准。';}
async function refreshModels(){const button=$('#refreshModels');button.disabled=true;try{const r=await fetch('/api/models');const j=await r.json();if(!r.ok)throw Error(j.error||'模型列表读取失败');const current=localStorage.getItem('texture-workbench-model');$('#modelSelect').innerHTML=j.models.map(m=>`<option value="${escapeHTML(m)}">${escapeHTML(modelLabel(m))}</option>`).join('')+'<option value="__custom">手动输入模型名称…</option>';if(j.models.includes(current))$('#modelSelect').value=current;else if(j.models.includes('doubao-seedream-5-0-260128'))$('#modelSelect').value='doubao-seedream-5-0-260128';state.api.model=$('#modelSelect').value;showModelFacts(state.api.model);$('#customModel').hidden=true;}catch(e){toast(e.message,true);}finally{button.disabled=false;}}
$('#refreshModels').onclick=refreshModels;
fetch('/api/config').then(r=>r.json()).then(config=>{if(!config.configured)return;state.serverConfig=config;state.useServerConfig=true;state.api.baseUrl=config.baseUrl;if(config.model)state.api.model=config.model;$('#apiStatus').textContent='接口已连接';$('#envChoice').hidden=false;return refreshModels();}).catch(()=>{});
